const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const date = yesterday.toISOString().split('T')[0]; // 2026-05-07
const parts = date.split('-');
const curatedPath = parts[0] + '/' + parts[1] + '/' + parts[2] + '/datos.csv';

return [{
  json: {
    date: date,
    curatedUrl: `http://minio:9000/curated-zone/${curatedPath}`
  }
}];

const csvText = $input.item.json.data;

const lines = csvText.trim().split('\n');
const headers = lines[0].split(',');

const rows = [];
for (let i = 1; i < lines.length; i++) {
  const values = lines[i].split(',');
  if (values.length !== headers.length) continue;

  const row = {};
  headers.forEach((h, idx) => {
    row[h.trim()] = values[idx] ? values[idx].trim() : null;
  });
  rows.push({ json: row });
}

return rows;
